 bool retained(std::uint32_t p,std::size_t n)const{return p<private_first||p>=private_end||(p>=packet+0x10u&&std::uint64_t(p)+n<=packet+0x60u)||(p>=packet-0x30u+0xcu&&std::uint64_t(p)+n<=packet-0x30u+0x20u)||(p>=vertices&&std::uint64_t(p)+n<=vertices+64u)||(p>=point&&std::uint64_t(p)+n<=point+16u);}
